/* Standalone 100% Offline Three.js Subset Engine for Powered Smart Hospital */
(function(global) {
  'use strict';

  var THREE = {};

  // Vector3
  THREE.Vector3 = function(x, y, z) {
    this.x = x || 0;
    this.y = y || 0;
    this.z = z || 0;
  };
  THREE.Vector3.prototype = {
    set: function(x, y, z) { this.x = x; this.y = y; this.z = z; return this; },
    copy: function(v) { this.x = v.x; this.y = v.y; this.z = v.z; return this; },
    add: function(v) { this.x += v.x; this.y += v.y; this.z += v.z; return this; },
    sub: function(v) { this.x -= v.x; this.y -= v.y; this.z -= v.z; return this; },
    multiplyScalar: function(s) { this.x *= s; this.y *= s; this.z *= s; return this; },
    length: function() { return Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z); },
    normalize: function() { var l = this.length() || 1; this.x /= l; this.y /= l; this.z /= l; return this; }
  };

  // Color
  THREE.Color = function(c) {
    this.r = 1; this.g = 1; this.b = 1;
    if (typeof c === 'string') this.setStyle(c);
    else if (typeof c === 'number') this.setHex(c);
  };
  THREE.Color.prototype = {
    setHex: function(hex) {
      this.r = ((hex >> 16) & 255) / 255;
      this.g = ((hex >> 8) & 255) / 255;
      this.b = (hex & 255) / 255;
      return this;
    },
    setStyle: function(str) {
      if (str.indexOf('#') === 0) {
        var hex = parseInt(str.substring(1), 16);
        if (str.length === 4) {
          var r = (hex >> 8) & 15, g = (hex >> 4) & 15, b = hex & 15;
          hex = (r << 20) | (r << 16) | (g << 12) | (g << 8) | (b << 4) | b;
        }
        return this.setHex(hex);
      }
      return this;
    },
    getHexString: function() {
      var r = Math.round(this.r * 255).toString(16).padStart(2, '0');
      var g = Math.round(this.g * 255).toString(16).padStart(2, '0');
      var b = Math.round(this.b * 255).toString(16).padStart(2, '0');
      return r + g + b;
    }
  };

  // Object3D
  THREE.Object3D = function() {
    this.position = new THREE.Vector3();
    this.rotation = new THREE.Vector3();
    this.scale = new THREE.Vector3(1, 1, 1);
    this.children = [];
    this.parent = null;
    this.visible = true;
  };
  THREE.Object3D.prototype = {
    add: function(obj) {
      if (obj && obj !== this) {
        if (obj.parent) obj.parent.remove(obj);
        obj.parent = this;
        this.children.push(obj);
      }
      return this;
    },
    remove: function(obj) {
      var idx = this.children.indexOf(obj);
      if (idx !== -1) {
        obj.parent = null;
        this.children.splice(idx, 1);
      }
      return this;
    }
  };

  // Scene
  THREE.Scene = function() {
    THREE.Object3D.call(this);
  };
  THREE.Scene.prototype = Object.create(THREE.Object3D.prototype);

  // Camera
  THREE.PerspectiveCamera = function(fov, aspect, near, far) {
    THREE.Object3D.call(this);
    this.fov = fov || 50;
    this.aspect = aspect || 1;
    this.near = near || 0.1;
    this.far = far || 2000;
  };
  THREE.PerspectiveCamera.prototype = Object.create(THREE.Object3D.prototype);

  // Lights
  THREE.AmbientLight = function(color, intensity) {
    THREE.Object3D.call(this);
    this.color = new THREE.Color(color);
    this.intensity = intensity !== undefined ? intensity : 1;
  };
  THREE.AmbientLight.prototype = Object.create(THREE.Object3D.prototype);

  THREE.DirectionalLight = function(color, intensity) {
    THREE.Object3D.call(this);
    this.color = new THREE.Color(color);
    this.intensity = intensity !== undefined ? intensity : 1;
  };
  THREE.DirectionalLight.prototype = Object.create(THREE.Object3D.prototype);

  THREE.PointLight = function(color, intensity) {
    THREE.Object3D.call(this);
    this.color = new THREE.Color(color);
    this.intensity = intensity !== undefined ? intensity : 1;
  };
  THREE.PointLight.prototype = Object.create(THREE.Object3D.prototype);

  // Geometries
  THREE.BufferGeometry = function() {};
  THREE.BoxGeometry = function(w, h, d) { this.width = w; this.height = h; this.depth = d; };
  THREE.BoxGeometry.prototype = Object.create(THREE.BufferGeometry.prototype);

  THREE.SphereGeometry = function(r) { this.radius = r; };
  THREE.SphereGeometry.prototype = Object.create(THREE.BufferGeometry.prototype);

  THREE.TorusGeometry = function(r, tube) { this.radius = r; this.tube = tube; };
  THREE.TorusGeometry.prototype = Object.create(THREE.BufferGeometry.prototype);

  THREE.CylinderGeometry = function(rt, rb, h) { this.radiusTop = rt; this.radiusBottom = rb; this.height = h; };
  THREE.CylinderGeometry.prototype = Object.create(THREE.BufferGeometry.prototype);

  THREE.RingGeometry = function(ir, or) { this.innerRadius = ir; this.outerRadius = or; };
  THREE.RingGeometry.prototype = Object.create(THREE.BufferGeometry.prototype);

  // Materials
  THREE.Material = function() {
    this.color = new THREE.Color(0xffffff);
    this.opacity = 1;
    this.transparent = false;
    this.wireframe = false;
  };
  THREE.MeshBasicMaterial = function(opts) {
    THREE.Material.call(this);
    if (opts) {
      if (opts.color !== undefined) this.color = new THREE.Color(opts.color);
      if (opts.opacity !== undefined) this.opacity = opts.opacity;
      if (opts.transparent !== undefined) this.transparent = opts.transparent;
      if (opts.wireframe !== undefined) this.wireframe = opts.wireframe;
    }
  };
  THREE.MeshBasicMaterial.prototype = Object.create(THREE.Material.prototype);

  THREE.MeshPhongMaterial = function(opts) {
    THREE.MeshBasicMaterial.call(this, opts);
  };
  THREE.MeshPhongMaterial.prototype = Object.create(THREE.MeshBasicMaterial.prototype);

  THREE.ShaderMaterial = function(opts) {
    THREE.Material.call(this);
    opts = opts || {};
    this.uniforms = opts.uniforms || {};
    this.vertexShader = opts.vertexShader || '';
    this.fragmentShader = opts.fragmentShader || '';
  };
  THREE.ShaderMaterial.prototype = Object.create(THREE.Material.prototype);

  // Mesh
  THREE.Mesh = function(geometry, material) {
    THREE.Object3D.call(this);
    this.geometry = geometry;
    this.material = material;
  };
  THREE.Mesh.prototype = Object.create(THREE.Object3D.prototype);

  THREE.Group = function() {
    THREE.Object3D.call(this);
  };
  THREE.Group.prototype = Object.create(THREE.Object3D.prototype);

  // Canvas / WebGL Renderer
  THREE.WebGLRenderer = function(opts) {
    opts = opts || {};
    this.domElement = document.createElement('canvas');
    this.context = null;
    this._alpha = opts.alpha || false;
    this._antialias = opts.antialias || false;

    try {
      this.context = this.domElement.getContext('webgl2') || this.domElement.getContext('webgl') || this.domElement.getContext('experimental-webgl');
    } catch(e) {
      this.context = null;
    }
  };

  THREE.WebGLRenderer.prototype = {
    setSize: function(w, h) {
      this.domElement.width = w;
      this.domElement.height = h;
      this.domElement.style.width = w + 'px';
      this.domElement.style.height = h + 'px';
      if (this.context) {
        this.context.viewport(0, 0, w, h);
      }
    },
    setPixelRatio: function(ratio) {
      this._pixelRatio = ratio;
    },
    setClearColor: function(color, alpha) {
      this._clearColor = new THREE.Color(color);
      this._clearAlpha = alpha !== undefined ? alpha : 1;
      if (this.context) {
        var c = this._clearColor;
        this.context.clearColor(c.r, c.g, c.b, this._clearAlpha);
      }
    },
    render: function(scene, camera) {
      if (!this.context) return;
      var gl = this.context;
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    }
  };

  global.THREE = THREE;

})(typeof window !== 'undefined' ? window : this);
